"""
splash_screen_tk.py -- standalone startup splash for tkinter apps (SetupShucker).

Tkinter port of splash_screen-vhs.py (the PySide6 one): same idea, same art,
no Qt. Standard library only.

Typical use, right after the Tk root is created and BEFORE it is shown:

    from splash_screen_tk import show_splash
    root = tk.Tk()
    root.withdraw()                    # keep the main window hidden meanwhile
    show_splash(root, seconds=3.0)     # <-- the only added call
    root.deiconify()

show_splash() blocks for `seconds` while keeping Tk painting (it pumps
root.update() instead of sleeping, so the image stays on screen), then closes
the splash and returns. Any failure is swallowed so the app still starts.

The image is embedded below, so it is PyInstaller-safe with no --add-data.
Tk 8.6 decodes PNG natively but not JPEG, so the art is stored as a 256-colour
PNG (looks the same, ~364 KB instead of 1.2 MB full-colour). You can still
override it with an on-disk .png/.gif via image_name=...; if that file exists
it wins, otherwise the embedded image is used.
"""

import os
import sys
import time
import tkinter as tk


