def _resource_path(name: str) -> str:
    """Absolute path to an optional on-disk override image: _MEIPASS when
    compiled with PyInstaller, else this file's folder, else next to the exe."""
    for base in (getattr(sys, "_MEIPASS", None),
                 os.path.dirname(os.path.abspath(__file__)),
                 os.path.dirname(os.path.abspath(sys.executable))):
        if base:
            p = os.path.join(base, name)
            if os.path.isfile(p):
                return p
    return name


def _load_image(master, image_name: str):
    """PhotoImage for the splash, or None. On-disk override first, then the
    embedded image."""
    if image_name:
        try:
            return tk.PhotoImage(master=master, file=_resource_path(image_name))
        except tk.TclError:
            pass
    try:
        return tk.PhotoImage(master=master, format="png",
                             data="".join(_SPLASH_IMAGE_B64.split()))
    except tk.TclError:
        return None


def show_splash(root,
                seconds: float = 3.0,
                image_name: str = "",
                fallback_text: str = "Loading...") -> None:
    """Show a centred, borderless, always-on-top splash for `seconds`, then close.

    root          : the app's tk.Tk() (create it, withdraw it, then call this)
    seconds       : how long the splash stays up
    image_name    : optional .png/.gif on disk that overrides the embedded art
    fallback_text : shown on a dark card if no image can be loaded
    """
    win = None
    try:
        win = tk.Toplevel(root)
        win.overrideredirect(True)                 # no title bar / border
        try:
            win.attributes("-topmost", True)
        except tk.TclError:
            pass
        img = _load_image(win, image_name)
        if img is not None:
            lbl = tk.Label(win, image=img, borderwidth=0, highlightthickness=0)
            lbl.image = img                        # keep a reference
            w, h = img.width(), img.height()
        else:
            w, h = 480, 240
            lbl = tk.Label(win, text=fallback_text, bg="#141414", fg="white",
                           font=("Arial", 16))
        lbl.place(x=0, y=0, width=w, height=h)
        sw, sh = win.winfo_screenwidth(), win.winfo_screenheight()
        win.geometry(f"{w}x{h}+{max((sw - w) // 2, 0)}+{max((sh - h) // 2, 0)}")
        win.lift()
        win.update()

        # keep it painted for the full duration (pump events, don't just sleep)
        deadline = time.monotonic() + max(0.0, seconds)
        while time.monotonic() < deadline:
            root.update()
            time.sleep(0.01)
    except Exception as exc:
        # a splash is cosmetic; never let it stop the app from launching
        print(f"[splash] skipped: {exc}")
    finally:
        if win is not None:
            try:
                win.destroy()
                root.update_idletasks()
            except tk.TclError:
                pass


if __name__ == "__main__":
    # standalone smoke test: shows the embedded splash for 3 s, then exits
    _root = tk.Tk()
    _root.withdraw()
    show_splash(_root, seconds=3.0)
    _root.destroy()


